WITH kept_keys AS (SELECT customer_id, id FROM accounts INTERSECT SELECT customer_id, id FROM accounts WHERE opened_date BETWEEN '2025-01-01' AND '2025-07-17'), kept_rows AS (SELECT s.* FROM accounts s INNER JOIN kept_keys k ON s.customer_id = k.customer_id AND s.id = k.id) SELECT DATE_TRUNC('WEEK', opened_date) AS week_start, status, AVG(balance) FILTER (WHERE account_type = 'SAVINGS') AS savings_avg_balance, COUNT(*) FILTER (WHERE account_type = 'SAVINGS') AS savings_rows, APPROX_PERCENTILE(balance, ARRAY(0.25, 0.5, 0.75)) AS balance_quartiles, COUNT(*) FILTER (WHERE account_type = 'CHECKING') AS checking_rows, SIZE(COLLECT_SET(account_type)) AS num_account_types FROM kept_rows GROUP BY week_start, status ORDER BY checking_rows DESC NULLS LAST;
